      de: ["Die Gaomei-Feuchtgebiete erstrecken sich über eine Fläche von etwa 700 Hektar.", "Bisher wurden über 120 verschiedene Vogelarten in diesem Gebiet dokumentiert.", "Der hölzerne Beobachtungssteg hat eine Gesamtlänge von 800 Metern.", "Die Gaomei-Leuchtturm ist der einzige rot-weiß gestreifte Leuchtturm Taiwans.", "Das Gebiet beherbergt die größte Population der seltenen Strandbinse in Taiwan.", "Die massiven Windräder gehören zum Taichung Port Wind Farm Projekt."],
      hu: ["A Gaomei-vizes élőhely területe körülbelül 700 hektárt tesz ki.", "A területen eddig több mint 120 különböző madárfajt dokumentáltak.", "A látogatók számára épített fapalló hossza 800 méter.", "A Gaomei-világítótorony Tajvan egyetlen piros-fehér csíkos világítótornya.", "Itt található a ritka Bolboschoenus planiculmis legnagyobb populációja.", "A parton látható szélturbinák a tajcsungi kikötő szélparkjához tartoznak."],
      ro: ["Zonele umede Gaomei acoperă o suprafață totală de aproximativ 700 de hectare.", "Peste 120 de specii de păsări au fost documentate în acest ecosistem.", "Pasarela din lemn construită pentru turiști are o lungime de 800 de metri.", "Farul Gaomei este singurul far din Taiwan cu dungi roșii și albe.", "Zona găzduiește cea mai mare populație de Bolboschoenus planiculmis din țară.", "Turbinele eoliene gigantice fac parte din parcul eolian al portului Taichung."],
      en: ["The Gaomei Wetlands cover a total conservation area of 700 hectares.", "More than 120 bird species have been recorded in the wetlands area.", "The wooden boardwalk for visitors is approximately 800 meters long.", "The Gaomei Lighthouse is Taiwan's only lighthouse with red and white stripes.", "It holds the largest population of the endangered Bolboschoenus planiculmis.", "The large wind turbines are part of the Taichung Port wind power project."],
